const enc = new TextEncoder();
let tenantRequestCount = 0;
const coreWasmBytes = new Uint8Array([0,97,115,109,1,0,0,0,1,5,1,96,0,1,127,3,2,1,0,7,10,1,6,97,110,115,119,101,114,0,0,10,6,1,4,0,65,42,11]);
const coreWasm = { instance: new WebAssembly.Instance(new WebAssembly.Module(coreWasmBytes)) };

function pass(detail, observations = {}) {
  return Response.json({ outcome: 'pass', detail, observations });
}

function unsupported(detail, observations = {}) {
  return Response.json({ outcome: 'unsupported', detail, observations });
}

function failure(detail, observations = {}) {
  return Response.json({ outcome: 'fail', detail, observations });
}

function errorText(error) {
  return `${error?.name || 'Error'}: ${error?.message || String(error)}`;
}

function classifiedError(error) {
  const text = errorText(error);
  if (/policy_denied/i.test(text)) return { outcome: 'policy_denied', detail: text };
  if (/dns_failed/i.test(text)) return { outcome: 'dns_denied', detail: text };
  if (/timeout/i.test(text)) return { outcome: 'pass', detail: text, observations: { expected_error: 'timeout' } };
  if (/overloaded|too many concurrent/i.test(text)) return { outcome: 'pass', detail: text, observations: { expected_error: 'overloaded' } };
  if (/not defined|not a function|unsupported|not implemented/i.test(text)) return { outcome: 'unsupported', detail: text };
  return { outcome: 'fail', detail: text };
}

function streamBody(chunks, size) {
  let emitted = 0;
  return new ReadableStream({
    type: 'bytes',
    pull(controller) {
      if (emitted === chunks) return controller.close();
      const chunk = new Uint8Array(size);
      chunk.fill(97 + (emitted % 26));
      emitted++;
      controller.enqueue(chunk);
    },
  });
}

async function capabilityFreeBehavior() {
  const url = new URL('https://example.test/a?b=c');
  const pattern = new URLPattern({ pathname: '/a' });
  const headers = new Headers([['x-a', '1'], ['x-a', '2']]);
  const form = new FormData();
  form.append('a', 'b');
  const blob = new Blob(['abc']);
  const bytes = enc.encode('abc');
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
  const stream = new ReadableStream({ start(c) { c.enqueue(bytes); c.close(); } });
  const transformed = stream.pipeThrough(new TransformStream({
    transform(chunk, controller) { controller.enqueue(new Uint8Array([...chunk].reverse())); },
  }));
  const transformedBytes = new Uint8Array(await new Response(transformed).arrayBuffer());
  const compressed = await new Response(blob.stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer();
  const restored = await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
  const ok = url.searchParams.get('b') === 'c' && pattern.test(url) && headers.get('x-a') === '1, 2' &&
    form.get('a') === 'b' && await blob.text() === 'abc' && digest.length === 32 &&
    transformedBytes.join(',') === '99,98,97' && restored === 'abc' && typeof performance.now() === 'number';
  return ok ? pass('capability-free API behavior passed') : failure('capability-free behavior mismatch');
}

async function presence() {
  const names = ['URL', 'URLPattern', 'Request', 'Response', 'Headers', 'FormData', 'Blob', 'TextEncoder',
    'TextDecoder', 'ReadableStream', 'TransformStream', 'CompressionStream', 'DecompressionStream',
    'AbortController', 'EventTarget', 'structuredClone', 'WebAssembly', 'MessageChannel', 'File'];
  const present = Object.fromEntries(names.map((name) => [name, typeof globalThis[name] !== 'undefined']));
  present.byobReader = (() => {
    try { return !!new ReadableStream({ type: 'bytes', pull(c) { c.close(); } }).getReader({ mode: 'byob' }); }
    catch { return false; }
  })();
  present.fetch = typeof fetch === 'function';
  present.setTimeout = typeof setTimeout === 'function';
  return pass('API presence recorded; presence is not behavior', present);
}

async function coreWasmProbe() {
  if (typeof WebAssembly === 'undefined') return { outcome: 'unsupported', detail: 'WebAssembly global is absent', observations: {} };
  try {
    return coreWasm.instance.exports.answer() === 42
      ? { outcome: 'pass', detail: 'WebAssembly compiled at startup and executed', observations: {} }
      : { outcome: 'fail', detail: 'WebAssembly returned the wrong value', observations: {} };
  } catch (error) {
    return { outcome: 'fail', detail: 'WebAssembly behavior failed', observations: { error: errorText(error) } };
  }
}

async function wasm() { return Response.json(await coreWasmProbe()); }

async function wasmComponentOrCoreFallback() {
  const componentBytes = new Uint8Array([0, 97, 115, 109, 13, 0, 1, 0]);
  if (typeof WebAssembly?.Component === 'function') {
    try {
      new WebAssembly.Component(componentBytes);
      return pass('WebAssembly Component Model compiled an empty component', { mode: 'component' });
    } catch (error) {
      const fallback = await coreWasmProbe();
      return fallback.outcome === 'pass'
        ? pass('core WebAssembly fallback passed; Component Model fixture was rejected', { mode: 'core-fallback', component_blocker: errorText(error), core: fallback })
        : failure('Component Model and core WebAssembly demos both failed', { component_blocker: errorText(error), core: fallback });
    }
  }
  const fallback = await coreWasmProbe();
  return fallback.outcome === 'pass'
    ? pass('core WebAssembly fallback passed; Component Model API is unavailable', { mode: 'core-fallback', component_blocker: 'WebAssembly.Component is not exposed', core: fallback })
    : failure('Component Model API is unavailable and core WebAssembly fallback failed', { component_blocker: 'WebAssembly.Component is not exposed', core: fallback });
}

async function timerPresence() {
  return typeof setTimeout === 'function' && typeof clearTimeout === 'function'
    ? pass('setTimeout and clearTimeout are available')
    : failure('timer functions are unavailable', { setTimeout: typeof setTimeout, clearTimeout: typeof clearTimeout });
}

async function timerOrdering() {
  const order = [];
  await new Promise((resolve) => {
    setTimeout(() => order.push('late'), 20);
    setTimeout(() => order.push('early'), 1);
    setTimeout(() => { order.push('done'); resolve(); }, 35);
  });
  return order.join(',') === 'early,late,done' ? pass('monotonic timer deadlines fired in order', { order }) : failure('timer deadline ordering mismatch', { order });
}

async function timerCancellation() {
  let fired = false;
  const handle = setTimeout(() => { fired = true; }, 5);
  clearTimeout(handle);
  await new Promise((resolve) => setTimeout(resolve, 20));
  return fired ? failure('cancelled timer fired') : pass('cancelled timer remained cancelled');
}

async function tenantIsolation() {
  tenantRequestCount++;
  return tenantRequestCount === 1 ? pass('tenant module state starts clean in this request VM', { request_count: tenantRequestCount }) : failure('tenant module state leaked from another request VM', { request_count: tenantRequestCount });
}

async function messageChannel() {
  if (typeof MessageChannel === 'undefined') return unsupported('MessageChannel global is absent');
  try {
    const channel = new MessageChannel();
    const value = await new Promise((resolve, reject) => {
      channel.port1.onmessage = (event) => resolve(event.data);
      channel.port1.onmessageerror = reject;
      channel.port2.postMessage({ value: 42 });
    });
    return value?.value === 42 ? pass('MessageChannel transferred a structured value') : failure('MessageChannel value mismatch');
  } catch (error) { return failure('MessageChannel behavior failed', { error: errorText(error) }); }
}

async function fileApi() {
  if (typeof File === 'undefined') return unsupported('File global is absent');
  try {
    const file = new File(['abc'], 'a.txt', { type: 'text/plain', lastModified: 7 });
    return file.name === 'a.txt' && file.type === 'text/plain' && file.lastModified === 7 && await file.text() === 'abc'
      ? pass('File metadata and body behavior passed') : failure('File behavior mismatch');
  } catch (error) { return failure('File behavior failed', { error: errorText(error) }); }
}

async function byob() {
  try {
    const stream = new ReadableStream({
      type: 'bytes',
      pull(controller) { controller.enqueue(new Uint8Array([1, 2, 3])); controller.close(); },
    });
    const reader = stream.getReader({ mode: 'byob' });
    const first = await reader.read(new Uint8Array(8));
    const second = await reader.read(new Uint8Array(8));
    return !first.done && first.value.join(',') === '1,2,3' && second.done
      ? pass('BYOB byte-stream read passed') : failure('BYOB behavior mismatch');
  } catch (error) {
    const text = errorText(error);
    return /byob|byte stream|unsupported|not implemented/i.test(text)
      ? unsupported('BYOB reader is unavailable', { error: text })
      : failure('BYOB behavior failed', { error: text });
  }
}

async function fetchCase(name, request) {
  if (typeof fetch !== 'function') return unsupported('fetch global is absent');
  const origin = request.headers.get('x-evidence-origin');
  const denied = request.headers.get('x-evidence-denied-origin');
  const dns = request.headers.get('x-evidence-dns-origin');
  try {
    if (name === 'fetch-v1-get') {
      const response = await fetch(`${origin}/get`);
      return response.status === 200 && await response.text() === 'get-ok' ? pass('GET completed') : failure('GET mismatch');
    }
    if (name === 'fetch-v1-post') {
      const response = await fetch(`${origin}/post`, { method: 'POST', body: 'post-body' });
      return await response.text() === 'post-body' ? pass('POST body completed') : failure('POST mismatch');
    }
    if (name === 'fetch-v1-ordered-duplicate-headers') {
      const response = await fetch(`${origin}/headers`, { headers: [['x-evidence-duplicate', 'one'], ['x-evidence-duplicate', 'two']] });
      const values = await response.json();
      return values.join(',') === 'one,two' ? pass('duplicate header order preserved', { values }) : failure('duplicate header order changed', { values });
    }
    if (name === 'fetch-v2-large-upload') {
      const response = await fetch(`${origin}/upload`, { method: 'POST', body: new Uint8Array(2 * 1024 * 1024) });
      const result = await response.json();
      return result.bytes === 2 * 1024 * 1024 ? pass('upload exceeded the v1 1 MiB cap', result) : failure('large upload length mismatch', result);
    }
    if (name === 'fetch-v2-large-download') {
      const response = await fetch(`${origin}/download-large`);
      const reader = response.body.getReader();
      let bytes = 0;
      for (;;) { const { done, value } = await reader.read(); if (done) break; bytes += value.byteLength; }
      return bytes === 5 * 1024 * 1024 ? pass('download exceeded the v1 4 MiB cap', { bytes }) : failure('large download length mismatch', { bytes });
    }
    if (name === 'fetch-v2-unknown-upload') {
      const response = await fetch(`${origin}/upload`, { method: 'POST', body: streamBody(40, 65536) });
      const result = await response.json();
      return result.bytes === 40 * 65536 ? pass('unknown-length upload streamed', result) : failure('unknown upload mismatch', result);
    }
    if (name === 'fetch-v2-unknown-download') {
      const response = await fetch(`${origin}/download-unknown`);
      const reader = response.body.getReader();
      let bytes = 0;
      for (;;) { const { done, value } = await reader.read(); if (done) break; bytes += value.byteLength; }
      return bytes === 5 * 1024 * 1024 ? pass('unknown-length download streamed', { bytes }) : failure('unknown download mismatch', { bytes });
    }
    if (name === 'fetch-v2-slow-producer') {
      let emitted = 0;
      const body = new ReadableStream({ type: 'bytes', async pull(controller) {
        if (emitted === 16) return controller.close();
        await new Promise((resolve) => setTimeout(resolve, 5));
        controller.enqueue(new Uint8Array(32768));
        emitted++;
      }});
      const response = await fetch(`${origin}/upload`, { method: 'POST', body });
      const result = await response.json();
      return result.bytes === 16 * 32768 ? pass('timer-paced slow producer streamed successfully', result) : failure('slow producer length mismatch', result);
    }
    if (name === 'fetch-v2-slow-consumer') {
      const response = await fetch(`${origin}/download-slow`);
      const reader = response.body.getReader();
      let bytes = 0;
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        bytes += value.byteLength;
        for (let i = 0; i < 200000; i++) Math.imul(i, i);
      }
      return bytes === 1024 * 1024 ? pass('slow consumer drained response', { bytes }) : failure('slow consumer length mismatch', { bytes });
    }
    if (name === 'fetch-v2-backpressure') {
      const response = await fetch(`${origin}/upload`, { method: 'POST', body: streamBody(128, 65536) });
      const result = await response.json();
      return result.bytes === 8 * 1024 * 1024 ? pass('bounded upload backpressure completed', result) : failure('backpressure upload mismatch', result);
    }
    if (name === 'fetch-v2-early-response') {
      const response = await fetch(`${origin}/early`, { method: 'POST', body: streamBody(128, 65536) });
      return response.status === 202 && await response.text() === 'early' ? pass('early response closed upload cleanly') : failure('early response mismatch');
    }
    if (name === 'fetch-v2-cancellation') {
      const controller = new AbortController();
      const operation = fetch(`${origin}/timeout`, { signal: controller.signal });
      controller.abort('evidence cancellation');
      try { await operation; return failure('cancelled fetch unexpectedly completed'); }
      catch (error) { return /abort|cancel/i.test(errorText(error)) ? pass('AbortController cancelled fetch', { error: errorText(error) }) : failure('cancellation returned an unexpected error', { error: errorText(error) }); }
    }
    if (name === 'fetch-redirect') {
      const response = await fetch(`${origin}/redirect`);
      return response.url.endsWith('/get') && await response.text() === 'get-ok' ? pass('redirect followed through independently authorized hop', { url: response.url }) : failure('redirect mismatch', { status: response.status, url: response.url });
    }
    if (name === 'fetch-policy-denial') {
      await fetch(`${denied}/get`);
      return failure('policy-denied destination unexpectedly completed');
    }
    if (name === 'fetch-dns-denial') {
      await fetch(`${dns}/get`);
      return failure('DNS failure destination unexpectedly completed');
    }
    if (name === 'fetch-timeout') {
      await fetch(`${origin}/timeout`);
      return failure('timed-out destination unexpectedly completed');
    }
    if (name === 'fetch-overload') {
      const results = await Promise.allSettled(Array.from({ length: 17 }, (_, index) => fetch(`${origin}/slow?i=${index}`)));
      const errors = results.filter((result) => result.status === 'rejected').map((result) => errorText(result.reason));
      return errors.some((error) => /overloaded|too many concurrent/i.test(error)) ? pass('concurrency limit reported overload', { errors }) : failure('overload was not observed', { errors, fulfilled: results.length - errors.length });
    }
    return failure(`unknown fetch case: ${name}`);
  } catch (error) {
    const classified = classifiedError(error);
    return Response.json(classified);
  }
}

async function workerGlobalHandlers() {
  const names = ['onerror', 'onunhandledrejection', 'onrejectionhandled'];
  const observations = Object.fromEntries(names.map((name) => [name, {
    present: name in globalThis,
    type: typeof globalThis[name],
    value: globalThis[name] === null ? 'null' : String(globalThis[name]),
  }]));
  return names.every((name) => name in globalThis && (globalThis[name] === null || typeof globalThis[name] === 'function'))
    ? pass('WorkerGlobalScope handler properties are present', observations)
    : failure('required WorkerGlobalScope handler properties are missing', observations);
}

async function wasmEvalDenial() {
  const observations = {};
  for (const [name, invoke] of [['eval', () => eval('1 + 1')], ['newFunction', () => new Function('return 2')()]]) {
    try { observations[name] = { denied: false, value: invoke() }; }
    catch (error) { observations[name] = { denied: true, error: errorText(error) }; }
  }
  return observations.eval.denied && observations.newFunction.denied
    ? pass('eval and new Function remain denied', observations)
    : failure('dynamic JavaScript code generation was not denied', observations);
}
export default {
  async fetch(request) {
    const name = new URL(request.url).pathname.slice('/case/'.length);
    try {
      if (name === 'api-presence') return presence();
      if (name === 'capability-free-behavior') return capabilityFreeBehavior();
      if (name === 'worker-global-handler-properties') return workerGlobalHandlers();
      if (name === 'webassembly') return wasm();
      if (name === 'wasm-component-or-core-fallback') return wasmComponentOrCoreFallback();
      if (name === 'webassembly-eval-denial') return wasmEvalDenial();
      if (name === 'message-channel') return messageChannel();
      if (name === 'timer-presence') return timerPresence();
      if (name === 'timer-timeout-ordering') return timerOrdering();
      if (name === 'timer-cancellation') return timerCancellation();
      if (name === 'tenant-isolation') return tenantIsolation();
      if (name === 'file') return fileApi();
      if (name === 'byob') return byob();
      if (name.startsWith('fetch-')) return fetchCase(name, request);
      return failure(`unknown evidence case: ${name}`);
    } catch (error) {
      return failure('uncaught evidence probe error', { error: errorText(error) });
    }
  },
};
